scripts.meas:
"""Bounded finite Pass C tests for Lynde__Cheerful_Tormentor (Deck 31). Part A: seeded finite Monte Carlo goldfish of
commander and engine deployment (seed 31, fixed N, on the play, no mulligans, no opponent, no tutors, paired common random
numbers: each challenger replaces the cut card at the same library position). Part B: exhaustive finite rules-encoded
scenario grids. Neither part is a win-rate simulation."""
import json,re,random,itertools,collections
W='/workspace/d31w/'
def load(p):
    out=[]
    for l in open(p):
        m=re.match(r'(\d+)x (.+?)( \[Commander\])?$',l.strip())
        if m and not m.group(3): out+=[m.group(2)]*int(m.group(1))
    return out
base=load(W+'base.txt'); assert len(base)==99
def swap(d,pairs):
    d=d[:]
    for a,c in pairs: d[d.index(c)]=a
    return d
COURT=("Court of Vantress","Cruel Reality"); REPL=("Extravagant Replication","Curse of Death's Hold")
FINAL=[COURT,REPL]
CFG={"baseline":base,"single_plus_Court_of_Vantress_minus_Cruel_Reality":swap(base,[COURT]),
     "single_plus_Extravagant_Replication_minus_Curse_of_Deaths_Hold":swap(base,[REPL]),"candidate":swap(base,FINAL)}
for k,(a,c) in {"staged_plus_Staff_of_Compleation_minus_Nightscape_Familiar":("Staff of Compleation","Nightscape Familiar"),
    "PassC_plus_Curse_of_Chaos_minus_Curse_of_Echoes":("Curse of Chaos","Curse of Echoes"),
    "PassC_plus_Strionic_Resonator_minus_Nightscape_Familiar":("Strionic Resonator","Nightscape Familiar"),
    "PassC_plus_Beseech_the_Mirror_minus_Curse_of_the_Restless_Dead":("Beseech the Mirror","Curse of the Restless Dead"),
    "rejected_plus_Disturbing_Mirth_minus_Trespassers_Curse":("Disturbing Mirth","Trespasser's Curse"),
    "rejected_plus_Teferis_Ageless_Insight_minus_Curse_of_Unbinding":("Teferi's Ageless Insight","Curse of Unbinding"),
    "rejected_plus_Thoughtrender_Lamia_minus_Bitterheart_Witch":("Thoughtrender Lamia","Bitterheart Witch"),
    "rejected_plus_Curse_of_the_Bloody_Tome_minus_Maddening_Hex":("Curse of the Bloody Tome","Maddening Hex")}.items():
    CFG["on_candidate_"+k]=swap(CFG["candidate"],[(a,c)])
ANY="UBR"
LAND={"Island":("U",0),"Swamp":("B",0),"Mountain":("R",0),"Badlands":("BR",0),"Blood Crypt":("BR",0),"Steam Vents":("UR",0),"Watery Grave":("UB",0),
 "Underground Sea":("UB",0),"Volcanic Island":("UR",0),"Bloodstained Mire":(ANY,0),"Polluted Delta":(ANY,0),"Scalding Tarn":(ANY,0),"Marsh Flats":(ANY,0),
 "Flooded Strand":(ANY,0),"Misty Rainforest":(ANY,0),"Command Tower":(ANY,0),"Mana Confluence":(ANY,0),"City of Brass":(ANY,0),"Exotic Orchard":(ANY,0),
 "Luxury Suite":("BR",0),"Morphic Pool":("UB",0),"Training Center":("UR",0),"Shivan Reef":("UR",0),"Sulfurous Springs":("BR",0),
 "Riverglide Pathway // Lavaglide Pathway":("UR",0),"Xander's Lounge":(ANY,1),"Bojuka Bog":("B",1),"Ancient Tomb":("CC",0)}
ROCK={"Sol Ring":(1,["C","C"]),"Arcane Signet":(2,[ANY]),"Talisman of Creativity":(2,["UR"]),"Talisman of Dominance":(2,["UB"]),
      "Talisman of Indulgence":(2,["BR"]),"Dimir Signet":(2,["UB"]),"Rakdos Signet":(2,["BR"])}
def cost(n):
    return {"Nightscape Familiar":("B",1),"Claws of Gix":("",0),"Despotic Scepter":("",1),"Staff of Compleation":("",3),"Braids, Arisen Nightmare":("BB",1),
     "Paradox Haze":("U",2),"The Ninth Doctor":("UR",1),"Obeka, Splitter of Seconds":("UBR",1),"Court of Vantress":("UU",2),"Extravagant Replication":("UU",4),
     "Cruel Reality":("BB",5),"Curse of Death's Hold":("BB",3)}.get(n)
OUTLET={"Claws of Gix","Despotic Scepter","Staff of Compleation","Braids, Arisen Nightmare"}
UPK={"Paradox Haze","The Ninth Doctor","Obeka, Splitter of Seconds"}
ENG={"Court of Vantress","Extravagant Replication"}; CUTS={"Cruel Reality","Curse of Death's Hold"}
BLUE_RED={"Paradox Haze","The Ninth Doctor","Obeka, Splitter of Seconds","Court of Vantress","Extravagant Replication"}
def pay(srcs,need,g):
    if len(srcs)<len(need)+g: return None
    def dfs(i,used):
        if i==len(need): return used
        for j in sorted(range(len(srcs)),key=lambda j:len(srcs[j])):
            if j not in used and need[i] in srcs[j]:
                r=dfs(i+1,used|{j})
                if r is not None: return r
        return None
    u=dfs(0,frozenset())
    if u is None: return None
    rest=sorted([j for j in range(len(srcs)) if j not in u],key=lambda j:(srcs[j]!="C",len(srcs[j])))
    if len(rest)<g: return None
    return set(u)|set(rest[:g])
def game(deck,rnd,T=7):
    d=deck[:]; rnd.shuffle(d); hand=d[:7]; lib=d[7:]
    lands=[]; rocks=[]; bf=set(); lt=None; recs=[]
    for t in range(1,T+1):
        if t>1: hand.append(lib.pop(0))
        lh=[c for c in hand if c in LAND]; newt=False
        if lh:
            L=sorted(lh,key=lambda c:(LAND[c][1]==0) if t<=1 else (LAND[c][1]!=0))[0]
            hand.remove(L); lands.append(L); newt=LAND[L][1]!=0
        av=[]
        for i,x in enumerate(lands):
            if i==len(lands)-1 and newt: continue
            v=LAND[x][0]; av+=["C","C"] if v=="CC" else [v]
        for r in rocks: av+=ROCK[r][1]
        def take(need,g):
            nonlocal av
            u=pay(av,need,g)
            if u is None: return False
            av=[x for j,x in enumerate(av) if j not in u]; return True
        for r in sorted([c for c in hand if c in ROCK],key=lambda c:ROCK[c][0]):
            if take([],ROCK[r][0]): hand.remove(r); rocks.append(r); av+=ROCK[r][1]
        if "Nightscape Familiar" in hand and lt is None and take(["B"],1): hand.remove("Nightscape Familiar"); bf.add("Nightscape Familiar")
        red=1 if "Nightscape Familiar" in bf else 0
        if lt is None and take(["U","B","R"],1-red): lt=t
        if lt is not None:
            for grp in (OUTLET,UPK,ENG|CUTS):
                for n in sorted([c for c in hand if c in grp],key=lambda c:len(cost(c)[0])+cost(c)[1]):
                    col,g=cost(n); g=max(0,g-(red if n in BLUE_RED else 0))
                    if take(list(col),g): hand.remove(n); bf.add(n)
        recs.append(dict(cast=lt is not None,lynde_and_outlet=lt is not None and bool(bf&OUTLET),
            lynde_and_extra_upkeep=lt is not None and bool(bf&UPK),lynde_and_copy_engine=lt is not None and bool(bf&ENG),
            lynde_and_cut_card=lt is not None and bool(bf&CUTS)))
    return recs
def run(deck,seed=31,N=20000,T=7):
    rnd=random.Random(seed); acc=collections.defaultdict(collections.Counter)
    for _ in range(N):
        for t,o in enumerate(game(deck,rnd,T),1):
            for k,v in o.items(): acc[t][k]+=v
    return {f"turn {t}":{"P_Lynde_cast":round(a['cast']/N,4),"P_Lynde_plus_repeatable_sacrifice_outlet":round(a['lynde_and_outlet']/N,4),
        "P_Lynde_plus_extra_upkeep_source":round(a['lynde_and_extra_upkeep']/N,4),"P_Lynde_plus_Court_or_Replication":round(a['lynde_and_copy_engine']/N,4),
        "P_Lynde_plus_Cruel_Reality_or_Deaths_Hold":round(a['lynde_and_cut_card']/N,4)} for t,a in acc.items()}
# ---------------- Part B
SELF=["Curse of Thirst","Curse of Bloodletting","Curse of Misfortunes","Cruel Reality","Torment of Scarabs","Curse of Death's Hold"]
def upkeep(curses,board,hand):
    """Best ordering of your upkeep triggers with the listed Curses attached to YOU (returned by Lynde) and Lynde on the battlefield.
    Objective (lexicographic): keep Lynde, keep the other creature, lose least life, draw most cards."""
    curses=frozenset(curses); best=None
    # static Death's Hold applied when it returned at the previous end step (state-based actions before the upkeep)
    other=board; dh_kill=("Curse of Death's Hold" in curses and board=="Lynde_plus_X1_creature")
    if dh_kill: other="Lynde_only"
    trig=["Lynde"]+[c for c in ("Curse of Thirst","Curse of Misfortunes","Cruel Reality","Torment of Scarabs") if c in curses]
    for order in itertools.permutations(trig):
        for mis_fetch in ([False,True] if "Curse of Misfortunes" in trig else [False]):
            for moved in sorted(curses)+[None]:
                on=set(curses); lynde=True; oth=other!="Lynde_only"; life=0; cards=0; h=hand; ok=True; mv=None
                for tr in order:
                    if tr=="Lynde":
                        if moved is None or moved not in on: continue
                        on.discard(moved); cards+=2; h+=2; mv=moved
                    elif tr=="Curse of Misfortunes" and mis_fetch: on.add("benign_Curse_fetched")
                    elif tr=="Curse of Thirst":
                        dmg=len(on)
                        life+=dmg*(2 if "Curse of Bloodletting" in on else 1)
                    elif tr=="Cruel Reality":
                        if oth: oth=False
                        elif lynde: lynde=False
                        else: life+=5
                    elif tr=="Torment of Scarabs":
                        cur=[c for c in on]
                        if cur: on.discard(sorted(cur)[0])   # sacrifice a Curse attached to you: Lynde returns it at the next end step
                        elif h>0: h-=1; cards-=1
                        else: life+=3
                if moved is not None and mv is None: continue
                key=(lynde,oth,-life,cards)
                if best is None or key>best[0]: best=(key,dict(order=list(order),moved_by_Lynde=mv,misfortunes_fetch=mis_fetch,lynde_kept=lynde,
                    other_creature_kept=(oth if board!="Lynde_only" else None),other_creature_killed_by_Deaths_Hold=dh_kill,life_lost=life,net_cards=cards))
    return best[1]
def gridB():
    B={}
    rows=[]; g=collections.Counter(); cells=0
    for k in (1,2,3):
        for sub in itertools.combinations(SELF,k):
            for board in ("Lynde_only","Lynde_plus_X1_creature","Lynde_plus_toughness2plus_creature"):
                for hand in (0,1):
                    cells+=1; r=upkeep(sub,board,hand); rows.append(dict(curses_on_you=list(sub),board=board,hand=hand,**r))
                    tag="with_Cruel_Reality" if "Cruel Reality" in sub else "without_Cruel_Reality"
                    g[f"cells_{tag}"]+=1; g[f"Lynde_lost_{tag}"]+=not r["lynde_kept"]
                    g[f"other_creature_lost_{tag}"]+=(r["other_creature_kept"] is False)
                    t2="with_Deaths_Hold" if "Curse of Death's Hold" in sub else "without_Deaths_Hold"
                    g[f"cells_{t2}"]+=1; g[f"X1_creature_killed_{t2}"]+=r["other_creature_killed_by_Deaths_Hold"]
                    g["max_life_lost"]=max(g["max_life_lost"],r["life_lost"])
                    if "Curse of Thirst" in sub: g["Thirst_cells"]+=1; g["Thirst_life_lost_total"]+=r["life_lost"]
                    g["Torment_cells_zero_life"]+=("Torment of Scarabs" in sub and r["life_lost"]==0)
                    g["Torment_cells"]+=("Torment of Scarabs" in sub)
    B["B1_self_curse_upkeep_stack_best_ordering"]=dict(cells=cells,**g,rows=rows,notes="Frozen-cache Oracle with the listed Curses attached to you (Lynde returns every Curse put into your graveyard attached to you at the next end step). All your upkeep triggers are ordered by you (CR 503.1a, 603.3b); the grid enumerates every order, every Lynde move target and the optional Misfortunes fetch (modelled as a harmless Curse attached to you) and keeps the best line (keep Lynde, keep the other creature, least life lost, most cards). Cruel Reality's trigger fixes 'that player' when it triggers, so moving it with Lynde does not stop that upkeep's sacrifice. Curse of Thirst counts Curses attached to you on resolution and Bloodletting doubles it if still attached. Torment of Scarabs is paid by sacrificing a Curse attached to you (Lynde returns it). Curse of Death's Hold applies -1/-1 when it returns at the end step, so an X/1 (Nightscape Familiar 1/1) dies before the upkeep. Unweighted cells, not frequencies.")
    # B2 finite rules cases
    B["B2_rules_cases"]=dict(cases=[
     dict(case="Despotic Scepter or Claws of Gix destroys/sacrifices your Curse in your main phase",result="Lynde returns it at the beginning of your end step attached to you; it can be moved at your next upkeep (one-turn latency).",refs="Lynde Oracle; 603.7"),
     dict(case="Braids, Arisen Nightmare sacrifices a Curse at the beginning of your end step",result="Lynde's delayed trigger is created after 'the beginning of the end step' has passed, so the Curse returns at the NEXT end step (the next opponent's turn), still attached to you before your next upkeep: same one-turn latency; opponents each sacrifice an enchantment or lose 2 while you draw.",refs="603.7, 513.1"),
     dict(case="An opponent destroys a Curse attached to them during their turn",result="It returns attached to you at that turn's end step; at your upkeep Lynde moves it again for two cards.",refs="Lynde Oracle"),
     dict(case="The Curse card is exiled from your graveyard before the end step (Bojuka Bog, Relic)",result="The delayed trigger finds nothing; the Curse is lost.",refs="603.7c, 400.7"),
     dict(case="Accursed Witch // Infectious Curse: Infectious Curse is put into your graveyard",result="Lynde triggers (it was a Curse on the battlefield, 603.10a). In the graveyard the card has only its front-face characteristics (712.8a), a creature, not an Aura; an effect that puts a non-Aura onto the battlefield attached to a player puts it onto the battlefield unattached (303.4h), so Accursed Witch returns as a creature and its dies trigger can make Infectious Curse again.",refs="603.10a, 712.8a, 303.4h"),
     dict(case="Copy Enchantment or Mirrormade copying a Curse is put into your graveyard",result="Lynde triggers (look-back). The card returns; as it enters it may copy an enchantment on the battlefield; if it copies a Curse it enters as an Aura attached to you (the attachment Lynde specifies is legal for enchant player); if it copies a non-Aura it enters unattached (303.4h). Classified rules-encoded, moderate confidence.",refs="603.10a, 707.2, 303.4h"),
     dict(case="Court of Vantress (monarch) or Extravagant Replication makes a token copy of a Curse",result="The token Aura is not cast, so you choose the player it enchants as it enters (303.4f): attach it to yourself and Lynde moves it to an opponent at the same or next upkeep for two cards, or attach it straight to an opponent.",refs="303.4f, 111"),
     dict(case="A token copy of a Curse is put into your graveyard",result="Lynde triggers, but the token ceases to exist (704.5d, 111.7) and nothing returns.",refs="704.5d, 111.7"),
     dict(case="Court of Vantress while you are not the monarch becomes a copy of a Curse",result="It is an Aura attached to nothing and goes to the graveyard (704.5m); Lynde returns the Court of Vantress card at the next end step unattached (303.4h) and its enters trigger makes you the monarch again. Rules-encoded, moderate confidence; not relied on for the selection.",refs="704.5m, 603.10a, 303.4h"),
     dict(case="Extravagant Replication copying Paradox Haze",result="The token Haze enters attached to the player you choose (303.4f): on yourself it gives one more additional upkeep from the next turn; Haze copies stack (each is 'enchanted player's first upkeep each turn').",refs="303.4f, Paradox Haze Oracle"),
     dict(case="Extravagant Replication or Court copying a legendary permanent (Lynde, Obeka, The Ninth Doctor, Braids)",result="Legend rule (704.5j): one is put into the graveyard. Not a useful target.",refs="704.5j"),
     dict(case="Cruel Reality attached to you at your upkeep",result="Its trigger makes YOU sacrifice a creature or planeswalker (Lynde if she is your only one) even if Lynde moves it first, because 'that player' is fixed when it triggers.",refs="603.2, Cruel Reality Oracle")])
    # B3 extra-upkeep supply and copy-engine output for one of your turns
    rows=[]; g=collections.Counter(); cells=0
    for haze,doc,obeka,eng,start in itertools.product((0,1),("absent","tapped_last_turn","not_tapped"),("absent","connects_for_2"),
            ("none","Court_monarch","Court_not_monarch","Extravagant_Replication","Court_monarch_plus_Replication"),(0,1,3)):
        cells+=1
        ups=1+haze+(1 if doc=="tapped_last_turn" else 0)+(2 if obeka=="connects_for_2" else 0)
        per=(1 if eng in("Court_monarch","Extravagant_Replication") else 2 if eng=="Court_monarch_plus_Replication" else 0)
        on=start; draws=0; tokens=0
        for u in range(ups):
            tokens+=per; on+=per     # copy-engine trigger ordered first: the token Curse is attached to you (303.4f)
            if on>0: on-=1; draws+=2
        rows.append(dict(paradox_haze=haze,ninth_doctor=doc,obeka=obeka,engine=eng,curses_on_you_at_start=start,upkeeps=ups,Lynde_draws=draws,curse_tokens=tokens))
        g[f"draws_{eng}"]+=draws; g[f"tokens_{eng}"]+=tokens; g[f"cells_{eng}"]+=1
    B["B3_extra_upkeep_and_copy_engine_supply"]=dict(cells=cells,**g,rows=rows,notes="One of your turns. Upkeeps = 1 + Paradox Haze + The Ninth Doctor (only if it becomes untapped during your untap step) + Obeka's combat damage (2 power, after combat). At each upkeep the copy-engine trigger is ordered before Lynde's, its Curse token is attached to you (303.4f) and Lynde moves one Curse attached to you for two cards. Not-monarch Court is counted as producing no token (its become-a-copy mode is not modelled). Unweighted cells; the copy target is assumed to exist (any Curse you control for Replication, any enchantment for Court).")
    # B4 opponent removal on the cut card versus the add, with Lynde
    rows=[]; g=collections.Counter(); cells=0
    def rem(card,ev,board):
        curse=card in("Cruel Reality","Curse of Death's Hold")
        if ev=="Lynde_absent_card_destroyed" or not curse:
            return dict(returns_to_you=False,self_harm=False,lost=ev!="none")
        if ev in("destroyed","sacrificed_by_you"):
            if card=="Cruel Reality": return dict(returns_to_you=True,self_harm=True,lost=False,note="next upkeep you sacrifice a creature" + (" (Lynde)" if board=="Lynde_only" else ""))
            return dict(returns_to_you=True,self_harm=board!="Lynde_plus_toughness2plus_creature",lost=False,note="-1/-1 to your creatures until moved")
        if ev in("exiled","bounced"): return dict(returns_to_you=False,self_harm=False,lost=ev=="exiled")
        return dict(returns_to_you=False,self_harm=False,lost=False)
    for card,ev,board in itertools.product(("Cruel Reality","Curse of Death's Hold","Court of Vantress","Extravagant Replication"),
            ("none","destroyed","sacrificed_by_you","exiled","bounced","Lynde_absent_card_destroyed"),("Lynde_only","Lynde_plus_X1_creature","Lynde_plus_toughness2plus_creature")):
        cells+=1; r=rem(card,ev,board); rows.append(dict(card=card,event=ev,board=board,**r))
        k=card.replace(' ','_').replace("'",''); g[k+"_self_harm"]+=r["self_harm"]; g[k+"_returns"]+=r["returns_to_you"]
    B["B4_removal_and_return_cut_versus_add"]=dict(cells=cells,**g,rows=rows,notes="With Lynde on the battlefield a destroyed or sacrificed Curse returns attached to YOU. Cruel Reality then costs you a creature at your next upkeep (Lynde if alone); Curse of Death's Hold shrinks your creatures (Nightscape Familiar dies, Lynde 1/3) until Lynde moves it. Court of Vantress and Extravagant Replication are not Curses and never return to you. Unweighted cells.")
    return B
if __name__=="__main__":
    A={k:run(d) for k,d in CFG.items()}
    B=gridB(); json.dump({'A':A,'B':B},open(W+'meas31.json','w'),indent=1)
    for k,v in B.items(): print(k,{a:b for a,b in v.items() if a not in('notes','rows','cases')})
    for k,v in A.items(): print(k[:66].ljust(66),{t[5:]:tuple(r.values()) for t,r in v.items() if t in('turn 3','turn 4','turn 5','turn 7')})
